package com.bn.aliagent.insight.aggregate; import static org.junit.jupiter.api.Assertions.*; import java.time.*; import org.junit.jupiter.api.Test;
class AggregationRetentionServiceTest { @Test void cleansOnlyHourlyAndDailyAtTheirRetentionCutoffs(){var target=new Target();new AggregationRetentionService(target,Clock.fixed(Instant.parse("2026-07-01T00:00:00Z"),ZoneOffset.UTC)).clean("test-tenant",100);assertEquals(Instant.parse("2026-01-02T00:00:00Z"),target.hourly);assertEquals(LocalDate.of(2024,7,1),target.daily);} static final class Target implements AggregateRetentionTarget{Instant hourly;LocalDate daily;public int deleteHourlyBefore(String t,Instant c,int b){hourly=c;return 0;}public int deleteDailyBefore(String t,LocalDate c,int b){daily=c;return 0;}} }
